import{_ as a,b as p,c as t,g as d}from"./chunks/framework.86O3EbG5.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach-homework/10.md","filePath":"articles/ai/books/ai-modern-approach-homework/10.md"}'),o={name:"articles/ai/books/ai-modern-approach-homework/10.md"};function n(i,e,r,c,h,k){return p(),t("div",null,[...e[0]||(e[0]=[d('<p>基于斯图尔特.罗素《人工智能：现代方法（第4版)）》的第 10 章，根据此章节的重点，并出一些从 基础→进阶→综合 的练习题，能让我将本章的知识串联起来。</p><h2 id="简述在pddl中动作的前提-precondition-和效果-effect-的作用。给定一个fly-p-from-to-动作-描述使其能够发生的前提条件-以及执行后产生的效果。" tabindex="-1">简述在PDDL中动作的前提（precondition）和效果（effect）的作用。给定一个Fly(p, from, to)动作，描述使其能够发生的前提条件，以及执行后产生的效果。</h2><p>要点：前提定义了动作执行的“门槛”（如飞行器必须在起点且必须是飞机），效果定义了“结果”（如飞行器的位置变为终点）。可通过列举At(p, from)、Plane(p)等来说明。</p><h2 id="以下哪种状态表示是合法的pddl要素化状态" tabindex="-1">以下哪种状态表示是合法的PDDL要素化状态？</h2><p>A. At(Truck, Melbourne) ∧ At(Truck, Sydney) B. Poor ∧ Unknown C. At(Father(Fred), Sydney)</p><h2 id="手动模拟规划图-planning-graph-的前两层-s0→a0→s1-构建过程。" tabindex="-1">手动模拟规划图（Planning Graph）的前两层（S₀→A₀→S₁）构建过程。</h2><p>使用“蛋糕问题”建模：Have(Cake)表示拥有蛋糕，Eaten(Cake)表示蛋糕被吃过。初始状态S₀为Have(Cake) ∧ ¬Eaten(Cake)。动作为Eat(Cake)（前提Have(Cake)，效果Have(Cake) ∧ Eaten(Cake)）和Bake(Cake)（前提¬Have(Cake)，效果Have(Cake) ∧ ¬Eaten(Cake)）。</p><h2 id="将-积木世界-的以下自然语言描述转换为pddl" tabindex="-1">将“积木世界”的以下自然语言描述转换为PDDL：</h2><p>“初始状态：积木A和B都在桌上（clear），机器人手部是空的。目标：积木A在积木B上面。动作：Pick(x)：将积木x从桌上拿起。前提：积木x在桌上、x上无其它积木（clear）、机器人手为空。效果：机器人手上有x、桌上没有x。”</p><h2 id="分析前向搜索和后向搜索在积木世界问题中的适用性和效率。" tabindex="-1">分析前向搜索和后向搜索在积木世界问题中的适用性和效率。</h2><p>一个积木世界问题涉及3个积木。初始状态为A、B、C随机堆叠，目标为A在B上，B在C上。分别描述前向和后向搜索如何探索状态空间，并说明在何种情况下后向搜索可能优于前向搜索。</p><h2 id="设计一个合适的启发式函数-用于改进一个前向状态空间规划器。使用-航空货物运输-问题作为具体案例-描述你的启发式函数如何估计从当前状态到目标状态的代价。" tabindex="-1">设计一个合适的启发式函数，用于改进一个前向状态空间规划器。使用“航空货物运输”问题作为具体案例，描述你的启发式函数如何估计从当前状态到目标状态的代价。</h2><h2 id="为pddl规划问题中的不相关动作设计过滤方法。" tabindex="-1">为PDDL规划问题中的不相关动作设计过滤方法。</h2><p>给定一个复杂的PDDL规划问题，其中包含许多可能与当前目标无关的动作，提出一种过滤不相关动作的方法，以减少搜索空间。</p><h2 id="探究命题逻辑-sat-转化为规划问题的方法。" tabindex="-1">探究命题逻辑（SAT）转化为规划问题的方法。</h2><p>参考SATPLAN的基本概念，解释如何将一个经典规划问题编码为一系列随时间步骤增长的SAT实例，并利用高效的SAT求解器来寻找一个固定长度的规划。</p><h2 id="规划问题建模与实现——设计-机密邮件递送-的完整pddl描述。有三个地点-办公室、机房、会议室-一个机器人-它能携带一个存储芯片。机器人需要完成pickup-芯片-、dropoff-芯片-以及move-不同房间之间-的动作。请为这个规划任务编写完整的pddl域和问题文件。" tabindex="-1">规划问题建模与实现——设计“机密邮件递送”的完整PDDL描述。有三个地点（办公室、机房、会议室），一个机器人，它能携带一个存储芯片。机器人需要完成PickUp（芯片）、DropOff（芯片）以及Move（不同房间之间）的动作。请为这个规划任务编写完整的PDDL域和问题文件。</h2><h2 id="规划系统的设计、分析与诊断。" tabindex="-1">规划系统的设计、分析与诊断。</h2><p>你被要求设计一个物流公司的自动化包裹分拣规划系统。系统必须最大化每日处理的包裹数量，同时最小化机器人移动的能耗。</p><p>(a) 设计一个性能度量函数，恰当地平衡“处理包裹数量”和“能源消耗”这两个指标。</p><p>(b) 描述一个层级化规划方法，其中高级规划器决定包裹的路线和任务队列，低级规划器负责详细的运动控制。</p><p>(c) 假设在初始测试中，规划器耗费数小时为一个包含10个包裹的任务生成计划。分析可能的原因并提出加速方法（如使用更优启发式、调整搜索策略、使用SATPLAN或并行规划）。</p><p>(d) 真实环境中，包裹可能被错误分拣，或者机器人可能因电能耗尽而暂停。解释为什么经典的前向状态空间搜索在这种情况下会失效，并提出一个增强的执行监控和重新规划机制。</p>',23)])])}const _=a(o,[["render",n]]);export{s as __pageData,_ as default};
